// Adaptador genérico: construye la solicitud HTTP a partir de settings.operations[<operación>].
// Plantillas: "{{input.a.b}}", "{{settings.x}}", "{{envelope.trace_id}}". Si un string es
// exactamente una plantilla, se conserva el tipo del valor (número, objeto, arreglo).
const r = $json;
const s = r.settings || {};
const op = (s.operations || {})[r.operation];
const fail = (status, code, message) => ({ json: { skip: true, status, error: { code, message } } });
const SLOTS = ['catalog', 'inventory', 'order_registry', 'payment', 'invoicing', 'fulfillment', 'human_console', 'iam', 'knowledge_source', 'telemetry_export', 'crm'];
if (!op) return fail('NOT_SUPPORTED', 'OPERATION_NOT_CONFIGURED', 'settings.operations.' + r.operation + ' no está definido para el puerto ' + r.port);
if (!s.base_url) return fail('PERMANENT_ERROR', 'VALIDATION', 'falta settings.base_url');
if (!SLOTS.includes(s.credential_slot)) return fail('PERMANENT_ERROR', 'VALIDATION', 'settings.credential_slot inválido: ' + s.credential_slot);
const ctx = { input: r.input || {}, settings: Object.assign({}, s, { operations: undefined }), envelope: r.envelope || {} };
const get = (obj, path) => String(path).split('.').reduce((a, k) => {
  if (a === undefined || a === null) return undefined;
  const m = k.match(/^(.*)\[(\d+)\]$/);
  return m ? (m[1] ? a[m[1]] : a)?.[Number(m[2])] : a[k];
}, obj);
const render = (v) => {
  if (typeof v === 'string') {
    const whole = v.match(/^\{\{\s*([^}]+?)\s*\}\}$/);
    if (whole) { const x = get(ctx, whole[1]); return x === undefined ? null : x; }
    return v.replace(/\{\{\s*([^}]+?)\s*\}\}/g, (_, p) => { const x = get(ctx, p); return x === undefined || x === null ? '' : String(x); });
  }
  if (Array.isArray(v)) return v.map(render);
  if (v && typeof v === 'object') return Object.fromEntries(Object.entries(v).map(([k, x]) => [k, render(x)]));
  return v;
};
const renderPath = (v) => String(v || '').replace(/\{\{\s*([^}]+?)\s*\}\}/g, (_, p) => { const x = get(ctx, p); return x === undefined || x === null ? '' : encodeURIComponent(String(x)); });
const path = renderPath(op.path);
const query = op.query ? render(op.query) : null;
let url = s.base_url.replace(/\/$/, '') + (path.startsWith('/') ? path : '/' + path);
if (query) {
  const qs = Object.entries(query).filter(([, v]) => v !== null && v !== '').map(([k, v]) => encodeURIComponent(k) + '=' + encodeURIComponent(typeof v === 'object' ? JSON.stringify(v) : v)).join('&');
  if (qs) url += (url.includes('?') ? '&' : '?') + qs;
}
const method = (op.method || 'GET').toUpperCase();
const headers = Object.assign({ 'Accept': 'application/json', 'Content-Type': 'application/json' }, render(op.headers || {}));
const body = (method === 'GET' || method === 'DELETE' || op.body === undefined) ? '' : JSON.stringify(render(op.body));
return { json: { skip: false, slot: s.credential_slot, method, url, headers, body, timeout_ms: op.timeout_ms || s.timeout_ms || 10000 } };

// Adaptador genérico: interpreta la respuesta según settings.operations[<operación>]
const req = $('Solicitud del puerto').item.json;
const op = (req.settings.operations || {})[req.operation] || {};
const res = $json;
const code = res.statusCode;
let body = res.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { /* respuesta no JSON */ } }
const get = (obj, path) => String(path).split('.').reduce((a, k) => {
  if (a === undefined || a === null) return undefined;
  const m = k.match(/^(.*)\[(\d+)\]$/);
  return m ? (m[1] ? a[m[1]] : a)?.[Number(m[2])] : a[k];
}, obj);
const success = op.success_codes || null;
const isOk = success ? success.includes(code) : (code >= 200 && code < 300);
const notFound = (op.not_found_codes || [404]).includes(code);
if (isOk) {
  let data;
  if (op.response_map) {
    data = {};
    for (const [k, p] of Object.entries(op.response_map)) data[k] = get(body, p) ?? null;
  } else data = body;
  if (op.status_field && op.status_map && data && typeof data === 'object') {
    const raw = data[op.status_field];
    data.provider_status = raw ?? null;
    data[op.status_field] = op.status_map[raw] ?? op.status_map['*'] ?? 'unknown';
  }
  return { json: { status: 'OK', data, error: null } };
}
if (notFound) return { json: { status: 'NOT_FOUND', data: null, error: { code: 'NOT_FOUND', message: 'HTTP ' + code, http_status: code } } };
const sensitive = req.sensitive === true;
let status;
if (code === 429 || code === 408) status = 'RETRYABLE_ERROR';
else if (code >= 500) status = sensitive ? 'UNKNOWN' : 'RETRYABLE_ERROR';
else status = 'PERMANENT_ERROR';
const msg = (body && typeof body === 'object') ? JSON.stringify(body).slice(0, 500) : String(body ?? '').slice(0, 500);
return { json: { status, data: null, error: { code: 'HTTP_' + code, message: msg, http_status: code } } };

// Timeout o error de red: si la operación es sensible el resultado es INCIERTO (ASR-02)
const req = $('Solicitud del puerto').item.json;
const msg = $json.error?.message ?? String($json.error ?? 'error de red');
const status = req.sensitive === true ? 'UNKNOWN' : 'RETRYABLE_ERROR';
return { json: { status, data: null, error: { code: /timeout/i.test(msg) ? 'TIMEOUT' : 'NETWORK_ERROR', message: msg } } };

